CREATE FUNCTION safe_divide(a numeric, b numeric) RETURNS numeric
    LANGUAGE plpgsql
AS $$
BEGIN
    RETURN round(a / b, 2);
EXCEPTION
    WHEN division_by_zero THEN
        RETURN NULL;
END
$$;

SELECT safe_divide(10, 4) AS ten_by_four, safe_divide(1, 0) AS one_by_zero;

SELECT owner, balance, safe_divide(100, balance) AS times_into_100
FROM accounts
ORDER BY id;

