practice.solution:
CREATE FUNCTION safe_int(t text) RETURNS integer
    LANGUAGE plpgsql
AS $$
BEGIN
    RETURN t::integer;
EXCEPTION
    WHEN invalid_text_representation THEN
        RETURN -1;
END
$$;

SELECT safe_int('42') AS a, safe_int('abc') AS b, safe_int('3.5') AS c, safe_int('-7') AS d;

