CREATE FUNCTION deposit(who text, amount numeric) RETURNS text
    LANGUAGE plpgsql
AS $$
DECLARE
    new_balance numeric;
BEGIN
    IF amount <= 0 THEN
        RAISE EXCEPTION 'amount must be positive';
    END IF;
    UPDATE accounts SET balance = balance + amount WHERE owner = who;
    new_balance := (SELECT balance FROM accounts WHERE owner = who);
    RETURN new_balance::text;
EXCEPTION
    WHEN OTHERS THEN
        RETURN SQLERRM;
END
$$;

SELECT deposit('Cleo', 25) AS cleo, deposit('Ana', -5) AS ana, deposit('Ben', 0) AS ben;

SELECT * FROM accounts ORDER BY id;

