practice.solution:
CREATE FUNCTION open_account(who text, amount numeric) RETURNS text
    LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO accounts (owner, balance) VALUES (who, amount);
    RETURN 'opened';
EXCEPTION
    WHEN unique_violation THEN
        RETURN 'name taken';
    WHEN check_violation THEN
        RETURN 'negative balance';
END
$$;

SELECT open_account('Dev', 30) AS dev, open_account('Ana', 10) AS ana, open_account('Eve', -5) AS eve;

SELECT * FROM accounts ORDER BY id;
